//! The grammar-file frontend: section discovery, the self-hosted `@parser`
//! section parser, and the canonical Sexp dump used by `--dump-sexp`.

const std = @import("std");
const Allocator = std.mem.Allocator;
const diag = @import("../diag.zig");

/// The parser for the `@parser` section, generated by Nexus from
/// nexus.grammar (with lang.zig as its @lang module). Never hand-edit.
pub const parser = @import("parser.zig");
pub const Sexp = parser.Sexp;

pub const LexerParser = @import("lexer_section.zig").LexerParser;
pub const GrammarLowerer = @import("lower.zig").GrammarLowerer;

pub fn findSection(text: []const u8, marker: []const u8) ?usize {
    var pos: usize = 0;
    while (pos < text.len) {
        if ((pos == 0 or text[pos - 1] == '\n') and
            pos + marker.len <= text.len and
            std.mem.eql(u8, text[pos..][0..marker.len], marker))
        {
            return pos;
        }
        pos = std.mem.indexOfScalarPos(u8, text, pos, '\n') orelse text.len;
        if (pos < text.len) pos += 1;
    }
    return null;
}

/// The name in a line-leading `@lang = "name"` anywhere in the file. The
/// lexer generator needs it before the @parser section is parsed (and some
/// grammars put `@lang` above `@lexer`, where the frontend never sees it).
pub fn scanLangDirective(sourceText: []const u8) ?[]const u8 {
    const pos = findSection(sourceText, "@lang") orelse return null;
    var i = pos + 5;
    while (i < sourceText.len and (sourceText[i] == ' ' or sourceText[i] == '=' or sourceText[i] == '\t')) : (i += 1) {}
    if (i < sourceText.len and sourceText[i] == '"') {
        i += 1;
        const nameStart = i;
        while (i < sourceText.len and sourceText[i] != '"') : (i += 1) {}
        if (i < sourceText.len) return sourceText[nameStart..i];
    }
    return null;
}

/// The @parser section parsed by the generated frontend. The tree's `.src`
/// positions are offsets into `parserBody`; `source` maps them back to the
/// grammar file. Deinit `parser` when finished with the tree.
pub const Parsed = struct {
    parser: parser.Parser,
    sexp: parser.Sexp,
    parserBody: []const u8,
    source: diag.Source,
};

/// Parse the @parser section of `sourceText` (the whole grammar file). A
/// syntax error is reported as `path:line:col: error: ...` and returned
/// as error.ParseError.
pub fn parseGrammarSexp(allocator: Allocator, sourceText: []const u8, path: []const u8) !Parsed {
    const parserStart = findSection(sourceText, "@parser") orelse {
        return error.MissingParserSection;
    };
    const base = parserStart + "@parser".len;
    const source: diag.Source = .{ .path = path, .text = sourceText, .base = base };
    var p = parser.Parser.init(allocator, sourceText[base..]);
    errdefer p.deinit();
    const sexp = p.parseGrammar() catch |err| {
        if (err == error.ParseError) {
            const tok = p.current;
            const tokText = sourceText[base + tok.pos ..][0..tok.len];
            if (tok.cat == .eof or tok.cat == .newline or tok.cat == .cont or tok.cat == .next_alt) {
                diag.errAt(source, tok.pos, "syntax error: unexpected {s}", .{describe(tok.cat)});
            } else {
                diag.errAt(source, tok.pos, "syntax error: unexpected {s} '{s}'", .{ describe(tok.cat), tokText });
            }
        }
        return err;
    };
    return .{ .parser = p, .sexp = sexp, .parserBody = sourceText[base..], .source = source };
}

fn describe(cat: parser.TokenCat) []const u8 {
    return switch (cat) {
        .eof => "end of file",
        .newline => "end of line",
        .cont => "continuation line",
        .next_alt => "`|` line",
        .ident => "name",
        .token => "token name",
        .label => "label",
        .word => "action word",
        .string => "string",
        .integer => "number",
        .comment => "comment",
        .err => "character",
        else => "symbol",
    };
}

// =============================================================================
// S-expression pretty-printer
//
// Renders the output of the generated frontend parser in a canonical textual
// form suitable for golden-file comparison. Lists that contain no nested lists
// stay on a single line; any list with a nested list child breaks across
// lines with two-space indentation per level.
//
// Syntactic forms — each Sexp variant prints in an unmistakable wrapper:
//   .nil        → _
//   .tag        → bare tagName  (only ever appears as the first child of a
//                 non-empty list, so it never collides with src content)
//   .src        → `text`        backticks with `\\` and `` \` `` escaping
//   .str        → "text"        double-quoted
//   .list       → (child child ...)
// =============================================================================

pub fn dumpSexp(writer: anytype, sexp: Sexp, source: []const u8, indent: usize) !void {
    switch (sexp) {
        .nil => try writer.writeAll("_"),
        .tag => |t| try writer.writeAll(@tagName(t)),
        .src => |s| try dumpSrcText(writer, source[s.pos..][0..s.len]),
        .str => |s| try writer.print("\"{s}\"", .{s}),
        .list => |l| {
            const items = l.items();
            if (items.len == 0) {
                try writer.writeAll("()");
                return;
            }

            var hasNestedList = false;
            for (items) |item| switch (item) {
                .list => |sub| if (sub.len > 0) {
                    hasNestedList = true;
                    break;
                },
                else => {},
            };

            try writer.writeAll("(");
            if (!hasNestedList) {
                for (items, 0..) |item, i| {
                    if (i > 0) try writer.writeAll(" ");
                    try dumpSexp(writer, item, source, 0);
                }
            } else {
                try dumpSexp(writer, items[0], source, indent + 2);
                for (items[1..]) |item| {
                    try writer.writeAll("\n");
                    try writer.splatByteAll(' ', indent + 2);
                    try dumpSexp(writer, item, source, indent + 2);
                }
            }
            try writer.writeAll(")");
        },
    }
}

fn dumpSrcText(writer: anytype, text: []const u8) !void {
    try writer.writeByte('`');
    for (text) |c| {
        if (c == '`' or c == '\\') try writer.writeByte('\\');
        try writer.writeByte(c);
    }
    try writer.writeByte('`');
}
